"""Generic Rust support (``mod rt``) embedded in exported programs: opens the module, values."""

VALUES = r"""
/// Generic plumbing generated by Pipelab: values, elements, events and probe/slot wiring.
/// The rules themselves are explicit code in the `*Rules` types below.
#[allow(dead_code)]
mod rt {
    use super::*;
    use std::collections::{BTreeMap, VecDeque};
    use std::sync::atomic::{AtomicBool, Ordering};

    /// A dynamically typed value (property values, rule variables, message fields).
    #[derive(Clone, Debug, PartialEq)]
    pub enum Value {
        Null,
        Bool(bool),
        Int(i64),
        Float(f64),
        Str(String),
    }

    impl Value {
        /// The value as gst-launch would write it (`None` for `Null`).
        pub fn text(&self) -> Option<String> {
            match self {
                Value::Null => None,
                Value::Bool(b) => Some(if *b { "true" } else { "false" }.to_string()),
                Value::Int(i) => Some(i.to_string()),
                Value::Float(f) => Some(f.to_string()),
                Value::Str(s) => Some(s.clone()),
            }
        }
        pub fn number(&self) -> Option<f64> {
            match self {
                Value::Int(i) => Some(*i as f64),
                Value::Float(f) => Some(*f),
                Value::Str(s) => s.trim().parse().ok(),
                _ => None,
            }
        }
        pub fn as_string(&self) -> String {
            self.text().unwrap_or_default()
        }
        pub fn as_i64(&self) -> Option<i64> {
            self.number().map(|n| n as i64)
        }
        pub fn as_f64(&self) -> Option<f64> {
            self.number()
        }
        pub fn as_bool(&self) -> Option<bool> {
            match self {
                Value::Bool(b) => Some(*b),
                Value::Int(i) => Some(*i != 0),
                Value::Str(s) => match s.as_str() {
                    "true" | "1" | "yes" => Some(true),
                    "false" | "0" | "no" => Some(false),
                    _ => None,
                },
                _ => None,
            }
        }
    }

    impl From<&str> for Value {
        fn from(value: &str) -> Self {
            Value::Str(value.to_string())
        }
    }
    impl From<String> for Value {
        fn from(value: String) -> Self {
            Value::Str(value)
        }
    }
    impl From<i64> for Value {
        fn from(value: i64) -> Self {
            Value::Int(value)
        }
    }
    impl From<f64> for Value {
        fn from(value: f64) -> Self {
            Value::Float(value)
        }
    }
    impl From<bool> for Value {
        fn from(value: bool) -> Self {
            Value::Bool(value)
        }
    }
    impl<T: Into<Value>> From<Option<T>> for Value {
        fn from(value: Option<T>) -> Self {
            value.map_or(Value::Null, Into::into)
        }
    }

    #[derive(PartialEq)]
    enum Comparable {
        Null,
        Number(f64),
        Text(String),
    }

    fn comparable(value: &Value) -> Comparable {
        match value {
            Value::Null => Comparable::Null,
            Value::Bool(_) => Comparable::Text(value.as_string()),
            other => match other.number() {
                Some(n) => Comparable::Number(n),
                None => Comparable::Text(other.as_string()),
            },
        }
    }

    /// Numbers (also numeric strings) compare as numbers, everything else as text.
    pub fn compare(left: &Value, op: &str, right: &Value) -> bool {
        let (a, b) = (comparable(left), comparable(right));
        match (op, a, b) {
            ("==", a, b) => a == b,
            ("!=", a, b) => a != b,
            (op, Comparable::Number(a), Comparable::Number(b)) => match op {
                "<" => a < b,
                "<=" => a <= b,
                ">" => a > b,
                ">=" => a >= b,
                _ => false,
            },
            _ => false,
        }
    }

    pub fn arg(args: &[(String, Value)], name: &str) -> Option<Value> {
        args.iter().find(|(key, _)| key == name).map(|(_, value)| value.clone())
    }

    pub fn args(fields: Vec<(&str, Value)>) -> Vec<(String, Value)> {
        fields.into_iter().map(|(key, value)| (key.to_string(), value)).collect()
    }

    /// Replaces `{name}` placeholders.
    pub fn expand(text: &str, values: &[(&str, Value)]) -> String {
        let mut text = text.to_string();
        for (name, value) in values {
            text = text.replace(&format!("{{{name}}}"), &value.as_string());
        }
        text
    }

    pub fn to_value(value: &glib::Value) -> Value {
        if let Ok(v) = value.get::<bool>() {
            Value::Bool(v)
        } else if let Ok(v) = value.get::<i64>() {
            Value::Int(v)
        } else if let Ok(v) = value.get::<i32>() {
            Value::Int(v.into())
        } else if let Ok(v) = value.get::<u32>() {
            Value::Int(v.into())
        } else if let Ok(v) = value.get::<f64>() {
            Value::Float(v)
        } else if let Ok(v) = value.get::<String>() {
            Value::Str(v)
        } else {
            value.serialize().map_or(Value::Null, |text| Value::from(text.as_str()))
        }
    }

    /// An application message posted on the bus (by probe rules or API functions).
    #[derive(Clone, Debug)]
    pub struct AppMessage {
        pub name: String,
        pub fields: Vec<(String, Value)>,
        pub source: Option<String>,
    }

    impl AppMessage {
        pub fn new(structure: &gst::StructureRef, source: Option<&gst::Object>) -> Self {
            let fields =
                structure.iter().map(|(key, value)| (key.to_string(), to_value(value))).collect();
            let source = source.map(|s| s.name().to_string());
            AppMessage { name: structure.name().to_string(), fields, source }
        }
        pub fn field(&self, name: &str) -> Value {
            arg(&self.fields, name).unwrap_or(Value::Null)
        }
    }
"""
